-- إصلاحُ الملخَّصات المبتورة داخل اقتباسٍ قرآنيّ.
-- وُلِّد آليًّا بـ scripts/repair-truncated-summaries.py: كلُّ حرفٍ مُضافٍ
-- منقولٌ بحرفه من حقل body الخاصِّ بالصفِّ نفسِه، لا من خارجه.
BEGIN;
UPDATE sharia_rulings SET summary = 'اختلف الفقهاء في حكم صلاة الجماعة للرجل القادر على ثلاثة أقوال: (1) فرض عين: وهو قول الحنابلة ورواية عند الشافعي، استدلالاً بظاهر الأمر في قوله تعالى: ﴿وَارْكَعُوا مَعَ الرَّاكِعِينَ﴾ [البقرة: ٤٣]…'
  WHERE id = '325d0dfc-4733-499a-a8e2-89436c2578cf';
UPDATE sharia_rulings SET summary = 'الاستئذان واجب قبل الدخول على بيوت الآخرين. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا وَتُسَلِّمُوا﴾ [النور: ٢٧]…'
  WHERE id = '4888c4aa-b905-4ae8-a304-f3de461870f3';
UPDATE sharia_rulings SET summary = 'صلاة الجمعة فرض عين على كل مسلم ذكر حر مكلّف مقيم لا عذر له. دليلها قوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ﴾ [الجمعة: ٩]…'
  WHERE id = '8788d677-7710-42a5-9a7b-d2d458344895';
UPDATE sharia_rulings SET summary = 'اختلف الفقهاء في هذه المسألة: ذهب جمهور الفقهاء (المالكية والشافعية والحنابلة) إلى اشتراط الوضوء لمسّ المصحف استدلالاً بقوله تعالى: ﴿لَّا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ﴾ [الواقعة: ٧٩]…'
  WHERE id = '7c527ac5-7263-46e3-a58e-aa9a6f750d78';
UPDATE sharia_rulings SET summary = 'إبراهيم الخليل عليه السلام كسّر الأصنام في قومه ثم أُلقي في النار بأمر ملكهم النمرود. فأمر الله النار بقوله: ﴿يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ﴾ [الأنبياء: ٦٩]…'
  WHERE id = '35880b0c-e135-4051-822c-882e301c58bf';
UPDATE sharia_rulings SET summary = 'أيوب عليه السلام كان نبياً غنياً معافى. فابتلاه الله بمرض شديد وفقر وضيق، وصبر سنوات طويلة. ثم نادى ربه: ﴿أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ﴾ [الأنبياء: ٨٣]…'
  WHERE id = '9529c588-bce1-4e8a-a02d-87738de7b24b';
UPDATE sharia_rulings SET summary = 'يونس بن متّى أُرسل إلى أهل نينوى في الجزيرة الفراتية. خرج من قومه قبل الإذن الإلهي غاضباً، فركب السفينة فأُلقي في البحر فالتقمه الحوت. وفي بطن الحوت نادى: ﴿لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ﴾ [الأنبياء: ٨٧]…'
  WHERE id = 'df2bf198-e0fc-4bca-a694-f327717a8742';
UPDATE sharia_rulings SET summary = 'الصحابة رضوان الله عليهم هم من رأى النبي ﷺ أو لقيه مسلماً ومات على الإسلام. فضائلهم: (1) زكّاهم الله في القرآن ﴿وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ ... رَضِيَ اللَّهُ عَنْهُمْ﴾ [التوبة: ١٠٠]…'
  WHERE id = 'da8dd90d-f26d-4b8e-9a9c-abb9af1d8896';
COMMIT;
